/*
 * Heimdall Design System · camada visual sobre o Marsala DS
 * https://paulofga86.github.io/heimdall-design-system/
 *
 * Use depois do CSS do Marsala (tokens --primary, --card, --border, --radius, --chart-sem-* etc.).
 * Só usa tokens do Marsala, então segue o tema claro e escuro sozinho.
 */

/* ── Tokens ──────────────────────────────────────────────────────────────── */

/* Fundo do app, sombras e curva de movimento. */
:root {
  /* Cinza quase branco, sem tinta. */
  --heimdall-ground: oklch(0.975 0.002 286);
  --heimdall-sombra: 0 1px 2px rgb(15 15 25 / 0.035), 0 6px 20px -8px rgb(15 15 25 / 0.07);
  --heimdall-sombra-alta: 0 1px 3px rgb(15 15 25 / 0.04), 0 10px 26px -10px rgb(15 15 25 / 0.10);
  --heimdall-mola: cubic-bezier(0.22, 1, 0.36, 1);
}
.dark {
  --heimdall-ground: color-mix(in oklch, var(--background) 80%, black);
  --heimdall-sombra: 0 1px 2px rgb(0 0 0 / 0.25), 0 8px 24px -10px rgb(0 0 0 / 0.45);
  --heimdall-sombra-alta: 0 2px 4px rgb(0 0 0 / 0.3), 0 16px 36px -12px rgb(0 0 0 / 0.6);
}

.heimdall-ground {
  background: var(--heimdall-ground);
}

/* Bloco do bento: superfície do card, cantos largos, contorno quase invisível, sombra mínima. */
.heimdall-block {
  border-radius: calc(var(--radius) * 2.2);
  border: 1px solid color-mix(in oklch, var(--border) 70%, transparent);
  background: var(--card);
  box-shadow: var(--heimdall-sombra);
}

/* Bloco de destaque: vinho cheio com luz suave no alto. */
.heimdall-block-primary {
  border-radius: calc(var(--radius) * 2.2);
  color: var(--primary-foreground);
  box-shadow: var(--heimdall-sombra);
  background:
    radial-gradient(40rem 22rem at 85% -10%, color-mix(in oklch, white 16%, transparent), transparent 60%),
    radial-gradient(30rem 20rem at 0% 110%, color-mix(in oklch, black 22%, transparent), transparent 65%),
    var(--primary);
}

/* ── Microinterações ─────────────────────────────────────────────────────── */
/* Regra (Paulo): nada se mexe no hover — só a sombra ou a cor clareiam de leve. */

/* Tudo que leva a outra tela: a sombra ganha um toque a mais. */
.heimdall-acesso {
  box-shadow: var(--heimdall-sombra);
  transition: box-shadow 260ms var(--heimdall-mola);
}
.heimdall-acesso:hover {
  box-shadow: var(--heimdall-sombra-alta);
  border-color: color-mix(in oklch, var(--border) 70%, transparent);
}

/* Itens do menu: só a cor muda (já no componente). */
.heimdall-item-menu svg {
  transition: color 200ms var(--heimdall-mola);
}

/* Linhas dentro dos blocos: o fundo escurece um toque. */
.heimdall-linha {
  transition: background-color 200ms var(--heimdall-mola);
}
.heimdall-linha:hover {
  background-color: color-mix(in oklch, var(--muted) 100%, var(--foreground) 3%);
}

/* Botão principal: sombra suave em vinho. */
.heimdall-botao {
  transition: box-shadow 260ms var(--heimdall-mola), background-color 150ms;
}
.heimdall-botao:hover:not(:disabled) {
  box-shadow: 0 6px 16px -8px color-mix(in oklch, var(--primary) 45%, transparent);
}

/* Troca de tela: o conteúdo chega com um leve deslizar. */
.heimdall-entrada {
  animation: heimdall-entrada 260ms var(--heimdall-mola) both;
}
@keyframes heimdall-entrada {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .heimdall-entrada { animation: none; }
}

::selection {
  background: color-mix(in oklch, var(--primary) 22%, transparent);
}

/* ── Fluxo vigiado (ilustração do login) ─────────────────────────────────── */

/* Linha do tempo (9 s): Issue 2% · Branch 12% · MR 24% (para até o alerta ser corrigido, 52%) · Revisão 70% · Deploy 79%. */
.fluxo-pulso {
  offset-path: path("M70 80 L330 80 C395 80 395 210 330 210 L120 210");
  offset-rotate: 0deg;
  animation: fluxo-pulso 9s linear infinite;
}

@keyframes fluxo-pulso {
  0% { offset-distance: 0%; opacity: 0; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  3% { offset-distance: 0%; opacity: 1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  12% { offset-distance: 19.9%; opacity: 1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  24%, 52% { offset-distance: 39.9%; opacity: 1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  70% { offset-distance: 87.5%; opacity: 1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  79% { offset-distance: 100%; opacity: 1; }
  86%, 100% { offset-distance: 100%; opacity: 0; }
}

.fluxo-rastro {
  stroke-dasharray: 100;
  stroke-dashoffset: 100;
  animation: fluxo-rastro 9s linear infinite;
}

@keyframes fluxo-rastro {
  0%, 3% { stroke-dashoffset: 100; opacity: 1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  12% { stroke-dashoffset: 80.1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  24%, 52% { stroke-dashoffset: 60.1; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  70% { stroke-dashoffset: 12.5; animation-timing-function: cubic-bezier(0.45, 0, 0.25, 1); }
  79%, 92% { stroke-dashoffset: 0; opacity: 1; }
  97%, 100% { stroke-dashoffset: 0; opacity: 0; }
}

.fluxo-alerta { animation: fluxo-alerta 9s linear infinite; }
.fluxo-ok { animation: fluxo-ok 9s linear infinite; }
.fluxo-no-mr { animation: fluxo-no-mr 9s linear infinite; }
.fluxo-no-mr > span:first-child { animation: fluxo-no-mr-icone 9s linear infinite; }

@keyframes fluxo-no-mr {
  0%, 24% { box-shadow: 0 8px 24px -8px rgb(0 0 0 / 0.35), 0 0 0 0 transparent; }
  26%, 50% { box-shadow: 0 8px 24px -8px rgb(0 0 0 / 0.35), 0 0 0 3px var(--chart-sem-warning); }
  52%, 94% { box-shadow: 0 8px 24px -8px rgb(0 0 0 / 0.35), 0 0 0 3px var(--chart-sem-success); }
  98%, 100% { box-shadow: 0 8px 24px -8px rgb(0 0 0 / 0.35), 0 0 0 0 transparent; }
}

@keyframes fluxo-no-mr-icone {
  0%, 24% { background: color-mix(in oklch, var(--primary) 10%, transparent); color: var(--primary); }
  26%, 50% { background: var(--chart-sem-warning); color: #18181b; }
  52%, 94% { background: var(--chart-sem-success); color: #18181b; }
  98%, 100% { background: color-mix(in oklch, var(--primary) 10%, transparent); color: var(--primary); }
}

@keyframes fluxo-alerta {
  0%, 24% { opacity: 0; transform: translateY(4px) scale(0.96); }
  27%, 48% { opacity: 1; transform: none; }
  51%, 100% { opacity: 0; transform: translateY(-4px) scale(0.96); }
}

@keyframes fluxo-ok {
  0%, 51% { opacity: 0; transform: translateY(4px) scale(0.96); }
  54%, 92% { opacity: 1; transform: none; }
  96%, 100% { opacity: 0; }
}

/* Check de cada etapa: acende quando o pulso passa e fica até o ciclo recomeçar. */
.fluxo-check { opacity: 0; animation: 9s linear infinite; }
.fluxo-check-issue { animation-name: fluxo-check-issue; }
.fluxo-check-branch { animation-name: fluxo-check-branch; }
.fluxo-check-mr { animation-name: fluxo-check-mr; }
.fluxo-check-revisao { animation-name: fluxo-check-revisao; }
.fluxo-check-deploy { animation-name: fluxo-check-deploy; }

@keyframes fluxo-check-issue {
  0%, 3% { opacity: 0; transform: scale(0.4); }
  5% { opacity: 1; transform: scale(1.18); }
  7%, 94% { opacity: 1; transform: scale(1); }
  98%, 100% { opacity: 0; transform: scale(1); }
}
@keyframes fluxo-check-branch {
  0%, 12% { opacity: 0; transform: scale(0.4); }
  14% { opacity: 1; transform: scale(1.18); }
  16%, 94% { opacity: 1; transform: scale(1); }
  98%, 100% { opacity: 0; transform: scale(1); }
}
@keyframes fluxo-check-mr {
  0%, 52% { opacity: 0; transform: scale(0.4); }
  54% { opacity: 1; transform: scale(1.18); }
  56%, 94% { opacity: 1; transform: scale(1); }
  98%, 100% { opacity: 0; transform: scale(1); }
}
@keyframes fluxo-check-revisao {
  0%, 70% { opacity: 0; transform: scale(0.4); }
  72% { opacity: 1; transform: scale(1.18); }
  74%, 94% { opacity: 1; transform: scale(1); }
  98%, 100% { opacity: 0; transform: scale(1); }
}
@keyframes fluxo-check-deploy {
  0%, 79% { opacity: 0; transform: scale(0.4); }
  81% { opacity: 1; transform: scale(1.18); }
  83%, 94% { opacity: 1; transform: scale(1); }
  98%, 100% { opacity: 0; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .fluxo-pulso, .fluxo-alerta { animation: none; opacity: 0; }
  .fluxo-check { animation: none; opacity: 1; }
  .fluxo-no-mr, .fluxo-no-mr > span:first-child { animation: none; }
  .fluxo-rastro { animation: none; stroke-dashoffset: 0; }
  .fluxo-ok { animation: none; opacity: 1; transform: none; }
}
